theme.css:
#wemd{color:#4d4f46;background-color:#fdfdf8;font-family:'Inter', 'Segoe UI', -apple-system, BlinkMacSystemFont, 'PingFang SC', 'Noto Sans SC', 'Microsoft YaHei', sans-serif;font-size:14px;line-height:1.9;letter-spacing:0.02em;text-align:justify;padding:28px 16px;overflow-wrap:anywhere}
#wemd p{margin:0 0 1em;text-indent:0}
#wemd h1{font-size:26px;font-weight:800;color:#23251d;margin-top:2em;margin-bottom:1em;text-align:left}
#wemd h2{font-size:20px;font-weight:800;color:#23251d;margin-top:2.4em;margin-bottom:0.8em;text-align:left;border-bottom:1px solid #bfc1b7;padding-bottom:.4em}
#wemd h3{font-size:17px;font-weight:700;color:#23251d;margin-top:1.8em;margin-bottom:0.6em}
#wemd h4{font-size:14px;font-weight:600;color:#65675e;margin-top:1.4em;margin-bottom:0.5em}
#wemd blockquote{border-left:4px solid #1e1f23;background:#eeefe9;padding:14px 18px;color:#4d4f46;font-style:normal;margin:1.2em 0}
#wemd code{background-color:#eeefe9;color:#23251d;padding:2px 6px;border-radius:4px;font-size:0.9em;font-family:ui-monospace, 'Cascadia Code', 'Fira Code', Menlo, Monaco, Consolas, monospace}
#wemd pre{background:#eeefe9;border-radius:6px;padding:16px 20px;line-height:1.5;white-space:pre-wrap}
#wemd pre code{background:transparent;padding:0}
#wemd table{width:100%;border-collapse:collapse}
#wemd th, #wemd td{border:1px solid #bfc1b7;padding:10px 14px}
#wemd th{background:#eeefe9}
#wemd tr:nth-child(even){background:#fdfdf8}
#wemd ul, #wemd ol{padding-left:24px;margin:1em 0}
#wemd ul{list-style-type:disc}
#wemd ol{list-style-type:decimal}
#wemd li{margin-bottom:6px}
#wemd li::marker{color:#ed7b2f}
#wemd hr{border:0;border-top:1px solid #bfc1b7;margin:1.5em 0;width:100%}
#wemd img{max-width:100%;height:auto;border-radius:6px}
#wemd figcaption{font-size:13px;color:#65675e;text-align:center}
#wemd a{color:#ed7b2f;text-decoration:none}
#wemd strong{color:#ed7b2f;font-weight:700}
#wemd mark{background:#e5e7e0;padding:2px 5px;border-radius:4px}
